import {escapeHTML as esc} from './component-markings.mjs';
// Data-derived orthographic illustration, not a photograph or manufacturing drawing.
export function boardThumbnail(b){const [x0,y0,x1,y1]=b.bounds,w=x1-x0,h=y1-y0,scale=Math.min(470/w,270/h),ox=(570-w*scale)/2,oy=(320-h*scale)/2;
 const p=(x,y)=>[ox+(x-x0)*scale,oy+(y1-y)*scale];const num=n=>Number(n.toFixed(2));const pos=(x,y)=>p(x,y).map(num).join(' ');
 let out=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 360" role="img" aria-label="Ilustración de ${esc(b.title)} a partir de sus coordenadas"><defs><linearGradient id="pcb-${b.id}" x2="0" y2="1"><stop stop-color="#24664e"/><stop offset="1" stop-color="#123d31"/></linearGradient></defs><rect width="640" height="360" fill="#0a151c"/><ellipse cx="327" cy="264" rx="242" ry="48" fill="#000" opacity=".3"/><g transform="translate(95 22) matrix(.9 .08 -.22 .83 0 0)"><rect x="${ox}" y="${oy+8}" width="${w*scale}" height="${h*scale}" rx="7" fill="#082f26"/><rect x="${ox}" y="${oy}" width="${w*scale}" height="${h*scale}" rx="7" fill="url(#pcb-${b.id})" stroke="#6a987b" stroke-width="1"/>`;
 // A sampling is used only in the thumbnail. The interactive board retains all traces.
 const wires=b.nets.flatMap(n=>n.wires).filter(w=>w.layer===1),step=Math.max(1,Math.ceil(wires.length/650));out+='<g fill="none" stroke="#aeab62" opacity=".45" stroke-width=".7">';wires.forEach((t,i)=>{if(i%step===0)out+=`<path d="M${pos(t.x1,t.y1)}L${pos(t.x2,t.y2)}"/>`;});out+='</g>';
 for(const hole of b.holes||[]){const [x,y]=p(hole[0],hole[1]);out+=`<circle cx="${x}" cy="${y}" r="${Math.max(2,hole[2]*scale)}" fill="#07181b" stroke="#c3b97b" stroke-width="2"/>`;}
 for(const e of b.elements.filter(e=>!e.mirror).sort((a,b)=>b.y-a.y)){const [x,y]=p(e.x,e.y),bw=Math.max(2,(e.body?.[0]||(/^R|^C/.test(e.name)?1.6:3))*scale),bh=Math.max(2,(e.body?.[1]||(/^R|^C/.test(e.name)?.8:2))*scale),lift=Math.min(9,Math.max(2,bw*.13)),col=/^C\d/.test(e.name)?'#a28d66':/^L\d/.test(e.name)?'#58625f':'#253137';out+=`<g transform="translate(${num(x)} ${num(y)}) rotate(${-e.rot||0})"><rect x="${-bw/2+2}" y="${-bh/2+2}" width="${bw}" height="${bh}" rx="1" fill="#000" opacity=".45"/><rect x="${-bw/2}" y="${-bh/2-lift}" width="${bw}" height="${bh+lift}" rx="1" fill="#101a1d"/><rect x="${-bw/2}" y="${-bh/2-lift}" width="${bw}" height="${bh}" rx="1" fill="${col}" stroke="#bac8bf" stroke-opacity=".35" stroke-width=".6"/>${bw>24&&bh>16&&/^U[0-9]+$/.test(e.name)?`<text x="0" y="${-lift+2}" text-anchor="middle" font-family="monospace" font-size="6" fill="#ccd8cd">${esc(e.name)}</text>`:''}</g>`;}
 return out+'</g><text x="24" y="338" fill="#91aaa5" font-family="monospace" font-size="10" letter-spacing="1">VISTA ILUSTRADA · ABRIR MODELO INTERACTIVO ↗</text></svg>';
}
